-- EDA_IARA_ENCANTAR_V1
-- Conteúdo para a Iara prender o visitante: culinária, mistérios, natureza e cultura.
-- Idempotente: não repete títulos já cadastrados. Revisão de conteúdo: Thiago.
insert into public.conhecimento_eda (publico, tema, titulo, palavras, conteudo)
select v.publico, v.tema, v.titulo, v.palavras, v.conteudo from (values
  ('visitante', 'culinaria', $c$Tacacá na cuia$c$, ARRAY['tacaca','tucupi','jambu','cuia','goma','comida','culinaria','prato','tipico']::text[], $c$O tacacá é um caldo quente de tucupi (líquido amarelo tirado da mandioca brava) com goma de tapioca, folhas de jambu e camarão seco. É servido numa cuia e tomado no fim da tarde, aos golinhos, sem colher — o camarão e o jambu se pegam com um palitinho. O jambu deixa a boca levemente dormente e formigando, e é justamente essa a graça.$c$),
  ('visitante', 'culinaria', $c$X-caboquinho e o café regional$c$, ARRAY['x-caboquinho','caboquinho','tucuma','cafe regional','cafe da manha','sanduiche','queijo coalho','pacova','tapioca','merenda']::text[], $c$O x-caboquinho é o sanduíche mais querido de Manaus: pão francês com lascas de tucumã (fruto de uma palmeira, de polpa alaranjada e amanteigada), queijo coalho e banana pacovã frita. É estrela do "café regional", o café da manhã amazonense, que também traz tapioca, pupunha cozida, bolo de macaxeira e suco de cupuaçu. É reconhecido como patrimônio cultural imaterial de Manaus.$c$),
  ('visitante', 'culinaria', $c$Peixes da mesa amazonense$c$, ARRAY['peixe','tambaqui','pirarucu','jaraqui','tucunare','caldeirada','matrinxa','costela','comer','restaurante','almoco','janta','gastronomia']::text[], $c$Peixe é o coração da mesa amazonense. Os mais pedidos: costela de tambaqui assada na brasa; pirarucu, chamado de "bacalhau da Amazônia", que vira o famoso pirarucu de casaca (em camadas com banana e farinha); caldeirada de tucunaré; matrinxã assada; e o jaraqui frito, dono do ditado "quem come jaraqui não sai mais daqui". Quase tudo vem acompanhado de farinha, baião de dois, vinagrete e pimenta murupi.$c$),
  ('visitante', 'culinaria', $c$Farinha, mandioca e tucupi$c$, ARRAY['farinha','uarini','mandioca','macaxeira','beiju','tucupi','farinhada','ovinha']::text[], $c$A mandioca é a base de tudo. A mandioca brava é venenosa crua, e foram os povos indígenas que criaram a técnica de ralar, espremer no tipiti e torrar para transformá-la em farinha, beiju, goma de tapioca e tucupi. A farinha do Uarini, de bolinhas douradas e crocantes (a "ovinha"), é a mais famosa do Amazonas. No interior, a farinhada reúne a família inteira na casa de farinha.$c$),
  ('visitante', 'culinaria', $c$Frutas e sabores da floresta$c$, ARRAY['fruta','acai','cupuacu','guarana','bacaba','buriti','pupunha','castanha','sorvete','suco','doce','sobremesa','camu-camu']::text[], $c$A floresta tem sabores que pouca gente de fora conhece: cupuaçu (azedinho e perfumado, vira creme, suco e bombom), açaí (no Norte se toma puro e grosso, muitas vezes com farinha e peixe frito, não como sobremesa doce), bacaba, buriti, pupunha cozida com café, camu-camu (riquíssimo em vitamina C), castanha-do-brasil e o guaraná, cultivado tradicionalmente pelo povo Sateré-Mawé na região de Maués.$c$),
  ('visitante', 'misterio', $c$A lenda do Boto$c$, ARRAY['boto','lenda','encantado','festa','chapeu','rapaz','misterio','historia','filho do boto']::text[], $c$Conta a lenda que, nas noites de festa, o boto-cor-de-rosa sai do rio transformado num rapaz bonito, todo de branco, bom de dança e de conversa. Ele nunca tira o chapéu: é para esconder o furo no alto da cabeça por onde respira. Encanta a moça mais bonita da festa e, antes do amanhecer, volta para o rio. Por isso, no interior, criança de pai desconhecido é chamada com carinho de "filho do boto". É tradição popular ribeirinha.$c$),
  ('visitante', 'misterio', $c$Curupira, o guardião da mata$c$, ARRAY['curupira','lenda','mata','floresta','cacador','pes virados','misterio','guardiao','assombracao']::text[], $c$O Curupira é o protetor da floresta e dos bichos: um menino de cabelos cor de fogo e pés virados para trás. As pegadas ao contrário confundem caçadores que matam além da conta, e quem se perde na mata diz que foi ele que "enrolou o caminho". Os antigos ensinam a deixar um agrado, como fumo, para ele abrir a passagem. É uma das lendas mais antigas do Brasil, registrada desde o século XVI.$c$),
  ('visitante', 'misterio', $c$Mapinguari, o gigante da floresta$c$, ARRAY['mapinguari','lenda','monstro','gigante','misterio','medo','assombracao','preguica gigante']::text[], $c$O Mapinguari é o bicho mais temido das histórias da mata: um gigante peludo, de cheiro insuportável, pele que flecha não fura e, em muitas versões, um olho só e a boca na barriga. Seringueiros e caçadores contam que seu grito paralisa de medo. Há pesquisadores que já levantaram a hipótese de a lenda guardar a memória das preguiças-gigantes, extintas há milhares de anos — mas é só uma hipótese: a história é tradição popular.$c$),
  ('visitante', 'misterio', $c$Cobra Grande, a Boiúna$c$, ARRAY['cobra grande','boiuna','cobra','lenda','rio','misterio','sucuri','honorato','norato','fundo do rio']::text[], $c$A Cobra Grande, ou Boiúna, é a senhora do fundo dos rios. Dizem os antigos que seus olhos brilham como duas tochas na escuridão, que ela pode virar embarcação iluminada para enganar os canoeiros e que os sulcos do seu corpo abriram igarapés. A versão mais conhecida é a de Cobra Norato (Honorato), o irmão bom que foi desencantado. Lenda à parte, a sucuri de verdade vive na região e é uma das maiores cobras do mundo.$c$),
  ('visitante', 'misterio', $c$Matinta Pereira$c$, ARRAY['matinta','matinta pereira','lenda','assobio','passaro','noite','misterio','bruxa','velha']::text[], $c$Matinta Pereira é a velha que, à noite, vira pássaro e sai assobiando perto das casas — um assobio fino e comprido que arrepia. Para ela ir embora, o morador grita prometendo tabaco ou café. Na manhã seguinte, a primeira pessoa que bater à porta pedindo o prometido é a Matinta. Conta a tradição que o encanto passa de uma mulher para outra quando ela pergunta "quem quer?" e alguém responde "eu quero".$c$),
  ('visitante', 'misterio', $c$A lenda da vitória-régia$c$, ARRAY['vitoria-regia','vitoria regia','lenda','naia','jaci','lua','estrela das aguas','flor','misterio']::text[], $c$Conta a lenda que a jovem indígena Naiá se apaixonou por Jaci, a Lua, que transformava em estrelas as moças que escolhia. Numa noite, Naiá viu a Lua refletida no lago, mergulhou para tocá-la e se afogou. Com pena, Jaci a transformou numa estrela diferente: a "estrela das águas", a vitória-régia, cuja flor branca e perfumada só se abre à noite.$c$),
  ('visitante', 'misterio', $c$A lenda do guaraná$c$, ARRAY['guarana','lenda','satere','mawe','maues','olho','menino','misterio','origem']::text[], $c$Para o povo Sateré-Mawé, o guaraná nasceu dos olhos de um menino muito querido, morto por um espírito invejoso. Seguindo a orientação de Tupã, plantaram os olhos do menino, e deles brotou a planta. Por isso o fruto maduro, quando abre, parece um olho que observa quem passa. Os Sateré-Mawé são considerados os primeiros a domesticar o guaraná, na região de Maués.$c$),
  ('visitante', 'misterio', $c$O Encante, a cidade no fundo do rio$c$, ARRAY['encante','encantado','encantados','fundo do rio','cidade encantada','misterio','sobrenatural','visagem','lenda']::text[], $c$Muitos ribeirinhos contam que no fundo dos rios existe o Encante: uma cidade encantada, bonita e iluminada, onde moram os encantados, como o boto, a Cobra Grande e a própria Iara. Quem é levado para lá, dizem, não quer mais voltar. É por respeito ao Encante que os antigos pedem licença antes de entrar no rio e evitam banho em certas horas, como o meio-dia e as seis da tarde. É crença tradicional, contada com muito respeito.$c$),
  ('visitante', 'natureza', $c$Arquipélago de Mariuá$c$, ARRAY['mariua','arquipelago','ilhas','barcelos','praia','maior do mundo','natureza','paisagem','beleza']::text[], $c$Em frente a Barcelos fica o Arquipélago de Mariuá, considerado o maior arquipélago fluvial do mundo, com mais de 1.400 ilhas espalhadas pelo Rio Negro. Na seca (em geral de setembro a fevereiro) surgem praias de areia branca que contrastam com a água escura; na cheia, as ilhas viram labirinto de igapó para navegar de canoa. É berçário de peixes ornamentais e um dos melhores cenários de pesca do tucunaré.$c$),
  ('visitante', 'natureza', $c$Serra do Aracá e a Cachoeira do El Dorado$c$, ARRAY['araca','serra do araca','el dorado','eldorado','cachoeira','queda','tepui','trilha','expedicao','aventura','montanha']::text[], $c$No Parque Estadual da Serra do Aracá, em Barcelos, está a Cachoeira do El Dorado, considerada a maior queda livre do Brasil, com 353 metros. A serra é um tepui, montanha de topo plano típica do norte da Amazônia. Chegar lá é expedição de verdade: vários dias de barco pelos rios e trilha na mata, sempre com operadora e guias locais e na época certa do rio. A operadora confirma roteiro, preparo físico e autorizações.$c$),
  ('visitante', 'natureza', $c$Igapó, a floresta alagada$c$, ARRAY['igapo','floresta alagada','cheia','canoa','arvores','alagado','natureza','passeio de canoa']::text[], $c$Igapó é a floresta que o Rio Negro alaga na cheia. As árvores ficam meses com o tronco debaixo da água escura, e dá para remar de canoa entre as copas, num silêncio de espelho — a água preta reflete a mata como vidro. Muitos peixes entram no igapó para comer frutos e ajudam a espalhar sementes. Na seca, o mesmo lugar vira trilha a pé e praia.$c$),
  ('visitante', 'natureza', $c$O boto-cor-de-rosa de verdade$c$, ARRAY['boto','boto-cor-de-rosa','golfinho','tucuxi','animal','bicho','fauna','rosa','natureza']::text[], $c$O boto-cor-de-rosa é o maior golfinho de rio do mundo e pode passar de 2 metros. Nasce cinza e vai ficando rosado com a idade, principalmente os machos. Tem o pescoço flexível, que ajuda a manobrar entre as árvores do igapó. No Rio Negro ele divide as águas com o tucuxi, menor e cinzento. É um animal protegido: o certo é observar com respeito, sem perseguir e seguindo a orientação dos guias.$c$),
  ('visitante', 'natureza', $c$Pirarucu, o gigante das águas$c$, ARRAY['pirarucu','gigante','peixe grande','maior peixe','escama','manejo','natureza','bicho']::text[], $c$O pirarucu é um dos maiores peixes de escama de água doce do mundo: pode passar de 2 metros e de 100 quilos. Ele precisa subir à superfície para respirar ar, e é nesse "boiar" que os pescadores experientes o localizam. O nome vem do tupi: "pira" (peixe) e "urucum" (vermelho), pela cor da cauda. No Amazonas, o manejo comunitário ajudou a recuperar a espécie em várias áreas.$c$),
  ('visitante', 'natureza', $c$A vitória-régia$c$, ARRAY['vitoria-regia','vitoria regia','planta','flor','folha','lago','natureza','aquatica']::text[], $c$A vitória-régia é a maior planta aquática da Amazônia: suas folhas redondas podem passar de 2 metros de diâmetro e têm a borda levantada como uma bandeja. A flor abre ao anoitecer, branca e perfumada, e no dia seguinte fica rosada. Ela vive em lagos e águas calmas, e é mais fácil de ver em áreas de água barrenta, como nos arredores de Manaus.$c$),
  ('visitante', 'natureza', $c$Cardinal e os peixes ornamentais$c$, ARRAY['cardinal','peixe ornamental','ornamental','aquario','piaba','piabeiro','acara-disco','neon','natureza','barcelos']::text[], $c$Barcelos é conhecida como a terra dos peixes ornamentais. O mais famoso é o cardinal, um peixinho de faixa azul-neon e vermelha que vive nos igarapés e igapós do médio Rio Negro e é querido por aquaristas do mundo todo. Quem coleta são os piabeiros, com técnica artesanal passada de pai para filho. A pesca ornamental bem feita dá renda às famílias e valoriza a floresta em pé.$c$),
  ('visitante', 'natureza', $c$Sumaúma, a mãe da floresta$c$, ARRAY['sumauma','samauma','arvore','gigante','sapopema','floresta','natureza','mae da floresta']::text[], $c$A sumaúma é uma das maiores árvores da Amazônia e pode passar de 50 metros de altura. Suas raízes enormes, em forma de parede, são chamadas de sapopemas: batendo nelas, o som ecoa longe, e por isso eram usadas para comunicação na mata. Muitos povos a consideram sagrada, a "mãe da floresta", e sua paina leve já foi usada para encher travesseiros e colchões.$c$),
  ('visitante', 'cultura', $c$Vida ribeirinha$c$, ARRAY['ribeirinho','ribeirinha','palafita','flutuante','comunidade','rabeta','canoa','modo de vida','cultura','caboclo']::text[], $c$No interior do Amazonas, o rio é a estrada. As famílias ribeirinhas moram em casas de palafita ou em flutuantes que sobem e descem com a água, vão à escola e ao mercado de canoa ou rabeta (canoa com motor pequeno) e vivem no ritmo da cheia e da seca: pesca, roça de mandioca, farinhada e extrativismo. A rede é cama, sofá e berço. Visitar uma comunidade pede combinação prévia e respeito às regras de cada lugar.$c$),
  ('visitante', 'cultura', $c$Povos indígenas do Rio Negro$c$, ARRAY['indigena','indigenas','povos','etnia','tukano','baniwa','nheengatu','yanomami','sao gabriel','lingua','cultura','tradicao']::text[], $c$O Rio Negro é uma das regiões de maior diversidade indígena do Brasil, com mais de 20 povos, como Baniwa, Tukano, Baré, Desana e Yanomami. São Gabriel da Cachoeira é o município com maior proporção de população indígena do país e reconhece línguas indígenas como cooficiais, entre elas nheengatu, tukano e baniwa. O Sistema Agrícola Tradicional do Rio Negro, com suas roças de mandioca, é patrimônio cultural do Brasil. Visitas a terras indígenas dependem de autorização.$c$),
  ('visitante', 'cultura', $c$Artesanato: piaçava, arumã e sementes$c$, ARRAY['artesanato','piacava','aruma','cestaria','cesto','semente','lembranca','souvenir','comprar','presente','cultura']::text[], $c$Barcelos é terra da piaçava, fibra de palmeira usada em vassouras e também em cestos, bolsas e peças de artesanato. Do alto Rio Negro vem a cestaria de arumã do povo Baniwa, com grafismos tradicionais. Completam a lista as biojoias de sementes, as cuias pintadas e as peças em madeira. Comprar direto de artesãos e associações locais é a melhor forma de levar uma lembrança e deixar renda na comunidade.$c$),
  ('visitante', 'cultura', $c$Cirandas de Manacapuru$c$, ARRAY['ciranda','manacapuru','festival','danca','flor matizada','guerreiros mura','festa','cultura']::text[], $c$Manacapuru, perto de Manaus, é a terra da ciranda. No Festival de Cirandas, três agremiações — Flor Matizada, Tradicional e Guerreiros Mura — disputam o título com dança, música, fantasias e alegorias no Parque do Ingá. A festa costuma acontecer no fim de agosto; a data de cada ano deve ser confirmada antes de viajar.$c$)
) as v(publico, tema, titulo, palavras, conteudo)
where not exists (select 1 from public.conhecimento_eda k where k.titulo = v.titulo);
